def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or (s.get('last_result_was_error') and s.get('last_error_kind') in ('unknown_col', 'syntax')):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_handling'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'ready_to_commit_candidate'
    if p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        nb['candidate_answer_available'] = True
    if p.get('remaining_rounds_low'):
        nb['remaining_rounds_low'] = True
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Identifier/schema issue: run SHOW TABLES and DESCRIBE the exact table, then backtick every table or column name with spaces, punctuation, parentheses, or reserved words. Do not replace spaces with underscores.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect sample rows or distinct values for the filtered columns, then relax predicates or use LIKE. Preserve exact stored text, including commas, percent signs, unicode dashes, spaces, and newlines, and quote text literals.'
    elif stage == 'text_numeric_handling':
        msg = 'TEXT numerics: for ranking, sums, differences, or max/min, cast cleaned numeric substrings to SIGNED or DECIMAL. For lexicographic max/min over text, use a numeric cast expression rather than raw string comparison.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: first DESCRIBE the target table and backtick non-simple identifiers. Use INSERT, UPDATE, or DELETE with exact requested literals; an empty tool result can still mean the mutation ran.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Mutation verification: if rounds allow, SELECT the affected row or count to confirm the intended change, then commit. Do not infer failure from [] after a data-changing statement.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated SQL loop: change strategy by probing schema, sampling rows, or distinct values instead of rerunning the same query.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (p.get('mutation_not_attempted') or nb.get('stage') == 'mutation_needs_execution')):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task; use SQL evidence to provide the requested value or rows.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted') and not (p.get('remaining_rounds_low') and nb.get('stage') == 'mutation_needs_execution'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task, but no INSERT, UPDATE, or DELETE has been executed yet. Perform the mutation before committing.'}
    return None
